import{_ as i,c as a,o as t,ae as l}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"AI Platform Home Dashboard User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Content/user-content-view.md","filePath":"Content/user-content-view.md"}'),s={name:"Content/user-content-view.md"};function o(r,e,n,c,u,d){return t(),a("div",null,e[0]||(e[0]=[l('<h1 id="ai-platform-home-dashboard-user-guide" tabindex="-1">AI Platform Home Dashboard User Guide <a class="header-anchor" href="#ai-platform-home-dashboard-user-guide" aria-label="Permalink to &quot;AI Platform Home Dashboard User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-platform-home-dashboard-user-guide">AI Platform Home Dashboard User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-the-home-dashboard">Accessing the Home Dashboard</a></li><li><a href="#dashboard-overview">Dashboard Overview</a></li><li><a href="#navigation-cards">Navigation Cards</a><ul><li><a href="#ai-assistant-card">AI Assistant Card</a></li><li><a href="#manage-ai-content-card">Manage AI Content Card</a></li><li><a href="#performance-card">Performance Card</a></li><li><a href="#manage-users-card">Manage Users Card</a></li><li><a href="#knowledge-bases-card">Knowledge Bases Card</a></li><li><a href="#settings-card">Settings Card</a></li></ul></li><li><a href="#getting-started">Getting Started</a></li><li><a href="#role-based-access">Role-Based Access</a></li><li><a href="#interface-features">Interface Features</a><ul><li><a href="#visual-design">Visual Design</a></li><li><a href="#responsive-layout">Responsive Layout</a></li><li><a href="#interactive-elements">Interactive Elements</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Platform Home Dashboard provides a centralized starting point for accessing all major platform features and management tools. This gateway interface presents a clear, visually appealing overview of available modules with quick-access navigation cards. The Home Dashboard is designed to help administrators, content managers, and other authorized users quickly access the tools they need to configure and maintain the AI platform.</p><h2 id="accessing-the-home-dashboard" tabindex="-1">Accessing the Home Dashboard <a class="header-anchor" href="#accessing-the-home-dashboard" aria-label="Permalink to &quot;Accessing the Home Dashboard&quot;">​</a></h2><p>The Home Dashboard is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access the dashboard:</p><ol><li>Log in to the AI Platform</li><li>You&#39;ll be automatically directed to the Home Dashboard</li><li>Alternatively, click the &quot;Home&quot; icon in the main navigation menu from anywhere in the platform</li></ol><h2 id="dashboard-overview" tabindex="-1">Dashboard Overview <a class="header-anchor" href="#dashboard-overview" aria-label="Permalink to &quot;Dashboard Overview&quot;">​</a></h2><p>The Home Dashboard consists of these key components:</p><ol><li><strong>Welcome Header</strong>: Personalized greeting with your name</li><li><strong>Action Prompt</strong>: &quot;What would you like to do today?&quot;</li><li><strong>Learning Button</strong>: Quick access to platform learning resources</li><li><strong>Navigation Cards</strong>: Six major feature cards organized in a grid layout</li><li><strong>Background Design</strong>: Subtle radial gradient using the platform&#39;s primary color</li></ol><h2 id="navigation-cards" tabindex="-1">Navigation Cards <a class="header-anchor" href="#navigation-cards" aria-label="Permalink to &quot;Navigation Cards&quot;">​</a></h2><h3 id="ai-assistant-card" tabindex="-1">AI Assistant Card <a class="header-anchor" href="#ai-assistant-card" aria-label="Permalink to &quot;AI Assistant Card&quot;">​</a></h3><p>Primary interface card for accessing the AI chat assistant:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Primary color circular icon with chat/comments symbol</li><li>&quot;AI Assistant&quot; heading in large text</li><li>Brief description explaining its purpose</li></ul></li><li><p><strong>Functionality</strong>:</p><ul><li>Click anywhere on the card to launch the AI Assistant</li><li>&quot;Launch&quot; button provides an additional click target</li><li>Redirects to the /assistant path</li></ul></li><li><p><strong>Purpose</strong>:</p><ul><li>Main entry point for asking questions to the AI</li><li>Access conversational interface</li><li>Use AI capabilities for assistance</li></ul></li></ol><h3 id="manage-ai-content-card" tabindex="-1">Manage AI Content Card <a class="header-anchor" href="#manage-ai-content-card" aria-label="Permalink to &quot;Manage AI Content Card&quot;">​</a></h3><p>Card for accessing content management tools:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Blue circular icon with palette symbol</li><li>&quot;Manage AI Content&quot; heading</li><li>Description explaining content management purpose</li></ul></li><li><p><strong>Functionality</strong>:</p><ul><li>Click to access the content management interface</li><li>&quot;Manage&quot; button provides an additional click target</li><li>Redirects to /content/ContentListView path</li></ul></li><li><p><strong>Purpose</strong>:</p><ul><li>Add new content for AI knowledge</li><li>Edit existing content</li><li>Manage documents and information the AI can access</li></ul></li></ol><h3 id="performance-card" tabindex="-1">Performance Card <a class="header-anchor" href="#performance-card" aria-label="Permalink to &quot;Performance Card&quot;">​</a></h3><p>Analytics and reporting interface card:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Purple circular icon with chart symbol</li><li>&quot;Performance&quot; heading</li><li>Description about data evaluation and metrics</li></ul></li><li><p><strong>Functionality</strong>:</p><ul><li>Click card to access insights home</li><li>Two separate buttons: &quot;Platform&quot; and &quot;Insights&quot;</li><li>Redirects to /insights/InsightsHome path</li></ul></li><li><p><strong>Purpose</strong>:</p><ul><li>View platform performance metrics</li><li>Access analytics dashboards</li><li>Review AI usage statistics and trends</li></ul></li></ol><h3 id="manage-users-card" tabindex="-1">Manage Users Card <a class="header-anchor" href="#manage-users-card" aria-label="Permalink to &quot;Manage Users Card&quot;">​</a></h3><p>User administration interface card:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Cyan circular icon with user symbol</li><li>&quot;Manage Users&quot; heading</li><li>Description explaining user management capabilities</li></ul></li><li><p><strong>Functionality</strong>:</p><ul><li>Click to access the user management interface</li><li>&quot;Manage&quot; button provides an additional click target</li><li>Redirects to /users/UserList path</li></ul></li><li><p><strong>Purpose</strong>:</p><ul><li>Create new user accounts</li><li>Edit existing user information</li><li>Manage permissions and roles</li><li>Delete user accounts when needed</li></ul></li></ol><h3 id="knowledge-bases-card" tabindex="-1">Knowledge Bases Card <a class="header-anchor" href="#knowledge-bases-card" aria-label="Permalink to &quot;Knowledge Bases Card&quot;">​</a></h3><p>Knowledge base management interface card:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Slate gray circular icon with server symbol</li><li>&quot;Knowledge Bases&quot; heading</li><li>Description explaining knowledge base purpose</li></ul></li><li><p><strong>Functionality</strong>:</p><ul><li>Click to access knowledge base management</li><li>&quot;Manage&quot; button provides an additional click target</li><li>Redirects to /assistant/kb/KBListView path</li></ul></li><li><p><strong>Purpose</strong>:</p><ul><li>Create and configure knowledge bases</li><li>Manage AI information sources</li><li>Organize content into specialized knowledge domains</li></ul></li></ol><h3 id="settings-card" tabindex="-1">Settings Card <a class="header-anchor" href="#settings-card" aria-label="Permalink to &quot;Settings Card&quot;">​</a></h3><p>Platform and AI configuration card:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Orange circular icon with sliders symbol</li><li>&quot;Settings&quot; heading</li><li>Description mentioning two settings categories</li></ul></li><li><p><strong>Functionality</strong>:</p><ul><li>Click card to access main settings interface</li><li>Two separate buttons: &quot;Platform&quot; and &quot;AI Settings&quot;</li><li>Redirects to /assistant/settings/AssistantSettings path</li></ul></li><li><p><strong>Purpose</strong>:</p><ul><li>Configure platform-wide settings</li><li>Adjust AI behavior and capabilities</li><li>Manage system preferences</li></ul></li></ol><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>For new users of the platform:</p><ol><li>The &quot;Learn the platform&quot; button in the top-right provides quick access to learning resources</li><li>This takes you to the AI Assistant where you can ask questions about using the platform</li><li>Start with the AI Assistant card to familiarize yourself with basic functionality</li><li>Explore other cards based on your specific role and responsibilities</li></ol><h2 id="role-based-access" tabindex="-1">Role-Based Access <a class="header-anchor" href="#role-based-access" aria-label="Permalink to &quot;Role-Based Access&quot;">​</a></h2><p>Dashboard access and available features depend on your assigned role:</p><ol><li><p><strong>Admin Users</strong>:</p><ul><li>Full access to all dashboard cards</li><li>Complete management capabilities</li></ul></li><li><p><strong>Content Managers</strong>:</p><ul><li>Access focused on content management features</li><li>Limited access to administrative functions</li></ul></li><li><p><strong>General Managers</strong>:</p><ul><li>Access to operational features</li><li>May have restricted access to certain configuration options</li></ul></li></ol><p>The interface adapts to show only the features your role is authorized to access.</p><h2 id="interface-features" tabindex="-1">Interface Features <a class="header-anchor" href="#interface-features" aria-label="Permalink to &quot;Interface Features&quot;">​</a></h2><h3 id="visual-design" tabindex="-1">Visual Design <a class="header-anchor" href="#visual-design" aria-label="Permalink to &quot;Visual Design&quot;">​</a></h3><p>The dashboard employs a clean, modern design philosophy:</p><ol><li><p><strong>Color Coding</strong>:</p><ul><li>Each card features a distinct color scheme</li><li>Icons use consistent color patterns</li><li>Primary platform color establishes visual identity</li></ul></li><li><p><strong>Card Layout</strong>:</p><ul><li>Uniform card sizing for visual consistency</li><li>Adequate spacing between elements</li><li>Clear visual hierarchy with icons, headings, and descriptions</li></ul></li><li><p><strong>Background</strong>:</p><ul><li>Subtle radial gradient using the primary color</li><li>Creates depth without distracting from content</li><li>Adapts to light/dark mode preferences</li></ul></li></ol><h3 id="responsive-layout" tabindex="-1">Responsive Layout <a class="header-anchor" href="#responsive-layout" aria-label="Permalink to &quot;Responsive Layout&quot;">​</a></h3><p>The dashboard adapts to various screen sizes:</p><ol><li><p><strong>Desktop View</strong>:</p><ul><li>3×2 grid layout showcasing all cards</li><li>Full spacing and complete descriptions</li></ul></li><li><p><strong>Tablet View</strong>:</p><ul><li>Adjusted padding for medium screens</li><li>Maintains grid structure with slightly compressed spacing</li></ul></li><li><p><strong>Mobile View</strong>:</p><ul><li>Cards may stack vertically on very small screens</li><li>Padding adjusts automatically</li><li>Content remains accessible at all screen sizes</li></ul></li></ol><h3 id="interactive-elements" tabindex="-1">Interactive Elements <a class="header-anchor" href="#interactive-elements" aria-label="Permalink to &quot;Interactive Elements&quot;">​</a></h3><p>Cards include multiple interactive features:</p><ol><li><p><strong>Hover Effects</strong>:</p><ul><li>Cards display enhanced shadow on hover</li><li>Visual feedback indicates interactivity</li><li>Entire card area is clickable</li></ul></li><li><p><strong>Button Controls</strong>:</p><ul><li>Text buttons maintain consistent styling</li><li>Cards with multiple functions show separate buttons</li><li>All interactive elements have appropriate hover states</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective dashboard usage:</p><ol><li><p><strong>Navigation Efficiency</strong>:</p><ul><li>Use cards as quick shortcuts to main features</li><li>The dashboard serves as a home base for your workflow</li><li>Return to the dashboard when switching between major tasks</li></ul></li><li><p><strong>Role-Appropriate Activities</strong>:</p><ul><li>Focus on the cards most relevant to your role</li><li>Content managers should prioritize content and knowledge base cards</li><li>Administrators may need to access all cards regularly</li></ul></li><li><p><strong>Learning Resources</strong>:</p><ul><li>Use the &quot;Learn the platform&quot; button when needed</li><li>Ask the AI Assistant specific questions about platform features</li><li>Revisit learning resources when exploring new capabilities</li></ul></li><li><p><strong>Regular Check-ins</strong>:</p><ul><li>Visit the Performance card to monitor system usage</li><li>Check for new content requirements regularly</li><li>Review user management needs as your organization evolves</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Cards not appearing</p><ul><li>Check your user role permissions</li><li>Consult with your administrator about access rights</li><li>Try refreshing the page</li><li>Verify you&#39;re signed in with the correct account</li></ul><p><strong>Issue</strong>: Cards appear but don&#39;t navigate when clicked</p><ul><li>Check for JavaScript errors in your browser console</li><li>Try using the specific labeled buttons instead of clicking the card</li><li>Verify that your session hasn&#39;t timed out</li><li>Try using a different browser if issues persist</li></ul><p><strong>Issue</strong>: Dashboard loads slowly</p><ul><li>Check your internet connection</li><li>Try refreshing the page</li><li>Clear your browser cache</li><li>Disable browser extensions that might interfere with performance</li></ul><p><strong>Issue</strong>: Visual elements display incorrectly</p><ul><li>Ensure your browser is updated to the latest version</li><li>Check if dark mode settings match your preferences</li><li>Try adjusting zoom level if text appears too large or small</li><li>Test in a different browser to isolate browser-specific issues</li></ul><p><strong>Issue</strong>: Welcome header doesn&#39;t show your name</p><ul><li>Verify your user profile has a correctly configured first name</li><li>Check user settings to update your profile information</li><li>Sign out and sign back in to refresh session data</li></ul><hr><p>For additional assistance with the Home Dashboard, please contact your system administrator or refer to the platform documentation.</p>',65)]))}const p=i(s,[["render",o]]);export{g as __pageData,p as default};
